"""Zero-dependency Unicode normalization and ASCII transliteration primitives."""

from __future__ import annotations

import functools
import unicodedata
from typing import cast

__all__ = [
    "normalize_ascii",
    "normalize_unicode_nfkc",
]


def normalize_unicode_nfkc(text: str) -> str:
    """Normalize unicode to NFKC (converts mathematical/stylized Unicode to standard alphanumerics)."""
    if not text:
        return ""
    return unicodedata.normalize("NFKC", text)


@functools.lru_cache(maxsize=1)
def _ascii_diacritic_trans() -> dict[int, int | str | None]:
    """Build a C-accelerated translate table mirroring NFD + Mn-stripping + đ→d."""
    mapping: dict[str, str | None] = {"đ": "d", "Đ": "d"}
    # Scan relevant Latin, Vietnamese, Combining Diacritics, and Fullwidth blocks
    ranges = (
        range(0x0000, 0x2500),
        range(0x1DC0, 0x2000),
        range(0x20D0, 0x2100),
        range(0xFE20, 0xFE30),
        range(0xFF00, 0xFFF0),
    )
    for r in ranges:
        for char in map(chr, r):
            if unicodedata.category(char) == "Mn":
                mapping[char] = None
                continue
            decomposed = unicodedata.normalize("NFD", char)
            base = "".join(c for c in decomposed if unicodedata.category(c) != "Mn")
            if len(base) == 1 and base != char:
                mapping[char] = base
    return cast(dict[int, int | str | None], str.maketrans(mapping))


@functools.lru_cache(maxsize=32768)
def normalize_ascii(text: str | None) -> str:
    """Normalize string to lowercase, strip diacritics and convert đ/Đ to d."""
    if not text:
        return ""
    raw = str(text)
    if raw.isascii():
        return raw.lower().strip()
    normalized = unicodedata.normalize("NFKC", raw.lower().strip())
    return normalized.translate(_ascii_diacritic_trans())

